#!/usr/bin/env python3
"""Prepare dedicated unfinished boss drafts; polish only after the complete pass."""
import json
from pathlib import Path

HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[4]
DESIGNS=[
('thebes_anubis','테베 아누비스','A tall black JACKAL-headed Egyptian death guardian, long pointed ears and narrow muzzle, turquoise/gold nemes striped headdress, black-gold segmented cuirass, broad lapis collar, gold bracers, ivory linen kilt with jackal medallion, digitigrade black jackal feet. One broad gold khopesh sword in anatomical RIGHT hand, LEFT hand empty. No wings or human helmet.'),
('thebes_horus','테베 호루스','An imposing FALCON-headed Egyptian war guardian, hooked bird beak, red-gold double crown and cobalt-striped headcloth, ivory/gold scale cuirass, falcon-feather shoulder mantle, blue linen kilt, scaled bird feet. One curved silver/gold ceremonial sword in anatomical RIGHT hand, LEFT hand empty. No jackal ears or interchangeable human knight helmet.'),
('thebes_osiris','테베 오시리스','A green-skinned undead Egyptian pharaoh with tall white atef crown and two side plumes, narrow regal face and false beard, ancient gold/lapis broad collar, ivory mummy-wrap sleeves, green-gold armored torso, long split linen robe and wrapped feet. One broad hooked gold sword in anatomical RIGHT hand, LEFT hand empty. No falcon or jackal head; distinct pharaoh silhouette.'),
('arcmo','아크모','A unique towering dark knight commander, closed angular blue-steel helmet with a tall swept-back double crest, huge layered asymmetrical steel pauldrons, dark articulated armor with cold silver filigree, pale ash-blue torn cape, broad rectangular greatsword with a blue gemstone pommel in anatomical RIGHT hand, LEFT gauntlet empty. Heavy armored boots; distinctive tall crest, never Kurtz red cape or horn helmet.'),
('zeros','제로스','A unique dark sorcerer-knight, narrow crowned black iron helm with three gold prongs, purple-black engraved plate and high collar, broad gold geometric chest emblem, long split violet tabard, heavy articulated dark boots, one long narrow blacksteel sword with an ornate gold circular guard in anatomical RIGHT hand, LEFT gauntlet empty. Angular crown and split violet cloak distinguish from other dark knights.'),
('grim_reaper','그림 리퍼','A towering skeletal GRIM REAPER, visible ivory skull deep inside a huge ragged midnight hood, skeletal rib cage partly under layered charcoal robes, iron chain belt, long torn hanging sleeves and hanging robe strips. One giant long-handled curved silver SCYTHE gripped by anatomical RIGHT hand, LEFT skeletal hand empty. Floats slightly above ground, no humanoid knight legs exposed; robe hems and chain react to motion. No smoke or glow.'),
('dread_vampire','공포의 뱀파이어','A unique tall pale aristocratic male vampire lord, swept-back silver-black hair, sharp long ears and visible small fangs, crimson high standing collar, black embroidered frock armor with silver bat clasps, burgundy silk-lined long cape, fitted black trousers and pointed armored boots. One elegant dark silver sword in anatomical RIGHT hand, LEFT clawed hand empty. No wings or crown, preserve aristocratic predatory silhouette.'),
('prince_deus','교만의 왕자 데우스','A unique regal male dark prince caster, long platinum hair, narrow gold crown with tall central purple gem, severe angular face, black/gold royal armor with high purple collar and broad gold shoulder ornaments, long plum split cape and intricate brocade robe with visible armored boots. One long black-gold STAFF topped by an enclosed violet orb in anatomical RIGHT hand, LEFT hand free for spell gesture. No sword or vampire cape collar.'),
('albino_unicorn','알비노 유니콘','A unique large ALBINO UNICORN, exactly ONE horse head, one long twisted ivory forehead horn, pearl-white horse body, pale pink muzzle/inner ears, silver-white long mane and flowing tail, gold/silver small decorative brow and chest pieces, exactly FOUR anatomically connected horse legs and four hooves. No wings, rider, human arms, extra heads or extra horns. Noble strong horse silhouette, complete mane/tail/hooves; attacks by horn thrust and foreleg strike.'),
('ugnus','오만한 우그누스','A massive unique winged demon overlord, huge dark red muscular biped torso, bull-like horned demonic head with two wide black curled horns, large leathery dark bat WINGS attached to back, segmented black/gold spiked shoulder/forearm/shin armor, heavy gold chain loincloth, thick dark-red tail and clawed feet. One huge black iron sword in anatomical RIGHT hand, LEFT claw empty. Wing membranes, horn breadth and gold armor define its own silhouette; not the wingless Albino Demon.'),
('zenith_queen','왜곡의 제니스 퀸','A unique monstrous SPIDER QUEEN: regal pale female head and dark flowing hair under a thorn crown, armored purple-black female upper torso with exactly TWO clawed arms, merging naturally into ONE huge purple-black spider abdomen and exactly EIGHT segmented spider walking legs. Gold chitin ornaments, purple waist plating and hooked claws. No human legs, hand-held weapon or extra human torso. Eight spider legs spread naturally around connected thorax; distinct spider silhouette, no loose webs or effects.'),
('jopnir','욥니르','A huge unique MINOTAUR warlord, exactly one shaggy dark-brown BULL head with two massive forward-curving ivory horns, muscular brown furred biped torso, gold-edged heavy battered iron shoulder/forearm armor, braided beard, red-brown heavy leather war skirt, two powerful hoofed legs. One colossal engraved double-headed iron AXE in anatomical RIGHT hand, LEFT hand empty. Bull muzzle, wide horn span and hoof feet must remain, no human face or demon tail.'),
('iris','잔혹한 아이리스','A unique severe female VALKYRIE war commander, long flowing crimson hair, silver winged temple helmet, dark silver armor with emerald inlays, broad layered feather-shaped pauldrons, dark green split battle skirt, fitted steel greaves and boots, deep green short battle cape. One broad silver SWORD with emerald hilt in anatomical RIGHT hand, LEFT gauntlet empty. Tall athletic imposing silhouette, no bird wings on back or princess gown; keep red hair/winged helmet/green armor.'),
('isabelle','질투의 공주 이자벨','A unique pale royal female duelist princess, long raven-black braided hair, small intricate gold thorn tiara, violet eyes, ornate gold/black fitted plate with a distinct high white lace throat, asymmetrical violet silk split overskirt over black armored legs and gold boots, long violet ribbon cape. One slender gold-hilted silver SWORD in anatomical RIGHT hand, LEFT gauntlet empty. Preserve tiara, black braid, lace collar and violet ribbons; no Iris winged helmet or red hair.'),
('belial','탐욕의 여왕 벨리엘','A unique regal demonic queen caster, pale copper skin, long wavy bronze hair, tall branching gold crown with ruby stones, black/gold corseted royal armor and broad ruby-studded pauldrons, rich dark burgundy split gown with gold chains and visible gold armored boots, long black velvet cape with red lining. One gold STAFF with an ornate claw cage holding a red jewel in anatomical RIGHT hand, LEFT hand empty/free for spell gesture. Crown/chain silhouette, no reused Ice Queen wings or purple hair.')]

def write(p,data):
    p.parent.mkdir(parents=True,exist_ok=True)
    if p.exists(): assert p.read_text()==data,'Preserve prior request; use a new revision'
    else:p.write_text(data)

def main():
    scope=json.loads((ROOT/'data/pr122_monster_production_scope.json').read_text())
    existing={v['id']:v for v in scope['monsters']}
    actors=[]
    for slug,name,design in DESIGNS:
        key='monster:'+name
        assert existing[key]['kind']=='boss'
        actor=dict(id=key,name=name,slug=slug,quality_tier='mythic_transform',design_basis='Dedicated newly painted original interpretation of named boss and existing DB body archetype; no claim of extracting original game art.',design=design,draft_clip_count=0,required_draft_clips=33,approved=False)
        actors.append(actor)
        request=dict(prompt='Paint ONE complete canonical full-body MYTHIC-QUALITY isometric RPG boss source illustration. '+design+' Camera SOUTH-EAST front three-quarter facing down-right, orthographic/isometric at about30degree elevation. Relaxed alert neutral grounded stance; all distinctive body parts plainly visible and connected. Preserve anatomical RIGHT weapon ownership. Rich precise painted metal/fabric/anatomy detail appropriate to a unique mythic transformation, crisp readable silhouette, no color-swap generic rig. Entire body/weapon/ears/horns/wings/tail/feet in central sixty percent of transparent canvas, generous clear inset. Exactly one character, true transparent empty background, no cast shadow, floor, aura, particles, haze, scenery, text or extra figures. This dedicated source will anchor every later direction and action.',transparent_background=True)
        write(HERE/slug/'requests/canonical-v01.json',json.dumps(request,ensure_ascii=False,indent=2)+'\n')
    policy=dict(draft_first=True,complete_review_passes_before_bulk_fixes=1,normal_monster_scope='Frame omissions only; preserve all normal art',approved_boss_art_preserved=True,regenerate_normal_clips=False,attempts_per_draft=1,repeat_identical_error_retry=False,blocked_actor_does_not_stop_other_actors=True,final_integration_after_grouped_fixes=True,frame_overlap_solution=dict(existing_shared_tool='tools/pr122_reviewed_source_regions.py',layout='Explicit phase_grid3, original row-major 3columns x2rows',rules=['Preserve full original PNG/SHA and source phase order','Use exact whole-pose regions, never cut fixed cells through a body','Require disjoint owned regions; no foreign bodies or ambiguous fragments','Apply existing alpha16/alpha100 ownership proof for eligible six-pose sources','Retain genuinely merged bodies and outer-edge truncation as HOLD; no guard relaxation']))
    write(HERE/'plan.json',json.dumps(dict(schema='pr122-boss-draft-first-v1',policy=policy,actors=actors,already_authored_staging_actors=['monster:얼음 여왕','monster:알비노 데몬','monster:커츠','monster:죽음의 좀비 로드'],new_approvals=0),ensure_ascii=False,indent=2)+'\n')
    print(json.dumps(dict(new_boss_draft_actors=len(actors),required_clips=33*len(actors),normal_art_changes=0)))

if __name__=='__main__':main()
